mkdir -p "$TMPDIR/probe" && cat <<'EOF' > "$TMPDIR/probe/probe_test.go"
package pose

import (
	"os"
	"testing"
	"time"
)

// Reviewer probe (overlay only): the claim-conflict winner return, reached
// with the existing beforeContinuationClaim hook.
func TestZZProbeClaimConflictReturnsWinner(t *testing.T) {
	f := resumableRunFixture(t)
	plan, err := f.store.PlanReviewResume(f.run.RunID)
	if err != nil {
		t.Fatal(err)
	}
	var winner ReviewRun
	defer func() { beforeContinuationClaim = func() {} }()
	beforeContinuationClaim = func() {
		beforeContinuationClaim = func() {}
		dir, _ := reviewRunRuntimeDirPath(runtimeSourceOf(f.run))
		if err := os.Remove(dir); err != nil {
			t.Fatal(err)
		}
		other, err := f.store.PlanReviewResume(f.run.RunID)
		if err != nil {
			t.Fatal(err)
		}
		if winner, err = f.store.RunReviewDispatch(other, time.Now); err != nil {
			t.Fatal(err)
		}
	}
	got, err := f.store.RunReviewDispatch(plan, time.Now)
	if err != nil || winner.RunID == "" || got.RunID != winner.RunID {
		t.Fatalf("got %q %v, winner %q", got.RunID, err, winner.RunID)
	}
	runs, lost, err := f.store.ReadReviewRuns("")
	if err != nil || len(lost) != 0 || len(runs) != 2 {
		t.Fatalf("runs %d lost %v err %v", len(runs), lost, err)
	}
}
EOF
printf '{"Replace":{"%s/pose-mcp/internal/pose/zz_probe_test.go":"%s/probe/probe_test.go"}}\n' "$PWD" "$TMPDIR" > "$TMPDIR/probe/overlay.json"; go -C pose-mcp test ./internal/pose -overlay "$TMPDIR/probe/overlay.json" -run 'ZZProbe' -count=1 -v 2>&1 | tail -n 15; git status --short | head
